<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      &quot;typings/**/*&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // 类型定义文件</span></span>
